<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {basicSetup,EditorView} from 'codemirror';import {EditorState} from '@codemirror/state';import {javascript} from '@codemirror/lang-javascript';import {python} from '@codemirror/lang-python';import {json} from '@codemirror/lang-json';import {downloadArtifact} from './artifact-utils';
 export let code='';export let language='text';export let filename='artifact.txt';export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();let mount:HTMLDivElement,view:EditorView|null=null,draft=code,notice='';
 $: dirty=draft!==code;$: dispatch('dirty',{dirty});
 function revoked(){view?.destroy();view=null;draft='';dispatch('revoked');}
 function unloading(event:BeforeUnloadEvent){if(dirty){event.preventDefault();event.returnValue='';}}
 async function copy(){try{await navigator.clipboard.writeText(draft);notice='Copied';}catch{notice='Copy unavailable. Select text in the editor to copy.';}}
 function reset(){if(dirty&&!confirm('Discard changes and restore the original chat artifact?'))return;view?.dispatch({changes:{from:0,to:view.state.doc.length,insert:code}});notice='Original chat artifact restored.';}
 onMount(()=>{if(!companyId||!actorId||accessSignal.aborted){revoked();return;}const syntax=language==='javascript'||language==='typescript'?javascript({typescript:language==='typescript'}):language==='python'?python():language==='json'?json():[];view=new EditorView({parent:mount,state:EditorState.create({doc:code,extensions:[basicSetup,syntax,EditorView.lineWrapping,EditorView.contentAttributes.of({'aria-label':filename+' editor',spellcheck:'false'}),EditorView.updateListener.of(update=>{if(update.docChanged)draft=update.state.doc.toString();}),EditorView.theme({'&':{height:'100%',fontSize:'13px',backgroundColor:'#fff'},'.cm-scroller':{fontFamily:'ui-monospace,Consolas,monospace',overflow:'auto'},'.cm-content':{minHeight:'300px'}})]})});window.addEventListener('beforeunload',unloading);accessSignal.addEventListener('abort',revoked,{once:true});});
 onDestroy(()=>{view?.destroy();window.removeEventListener('beforeunload',unloading);accessSignal?.removeEventListener('abort',revoked);});
</script>
<section class="artifact-editor" aria-label="Chat artifact editor"><header><div><strong>{filename}</strong><small>{dirty?'Unsaved local changes':'Original chat artifact'} · {language}</small></div><div class="buttons"><button type="button" on:click={copy}>Copy</button><button type="button" on:click={()=>downloadArtifact(draft,filename)}>Download</button><button type="button" on:click={reset} disabled={!dirty}>Restore original</button></div></header><p class="context">Local draft from chat. Download to keep your changes. Editing here does not change the message or a company file.</p><div class="editor" bind:this={mount}></div>{#if notice}<p class="notice" role="status">{notice}</p>{/if}</section>
<style>.artifact-editor{display:flex;flex-direction:column;height:100%;min-height:0;background:#fff;color:#17233b}header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:18px;border-bottom:1px solid #e2e8f0;flex-wrap:wrap}strong{font-size:14px}small{display:block;font-size:11px;color:#64748b;margin-top:4px}.buttons{display:flex;gap:6px;flex-wrap:wrap}button{padding:7px 10px;border:1px solid #dce5f2;border-radius:7px;background:#f8faff;color:#334e75;font-size:11px;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.context,.notice{margin:0;padding:12px 18px;font-size:11px;line-height:1.6;color:#64748b;background:#f8faff;border-bottom:1px solid #e2e8f0}.editor{flex:1;min-height:0;overflow:hidden}.notice{background:#f0f7ff}</style>
